{
  "version": "0.2",
  "phases": {
    "pre_build": {
      "commands": [
        "aws ecr get-login-password --region \"$AWS_DEFAULT_REGION\" | docker login --username AWS --password-stdin \"${IMAGE_URI%/*}\""
      ]
    },
    "build": {
      "commands": [
        "docker build --pull --file \"$DOCKERFILE\" --tag \"$IMAGE_URI:$IMAGE_TAG\" ."
      ]
    },
    "post_build": {
      "commands": [
        "docker push \"$IMAGE_URI:$IMAGE_TAG\""
      ]
    }
  }
}

